import { readFile } from "node:fs/promises";
import { join } from "node:path";
import type { HostGitHubClient } from "@grok/agent-sdk";
import { defineTool } from "@grok/agent-sdk/tools";
import { z } from "zod";
import { agentsPath, parseRepo, updateBranch } from "../lib/paths.js";

const file = z.object({
  path: z.string().min(1).max(240),
  content: z.string().min(1).max(64_000),
});

type File = z.infer<typeof file>;
type Octokit = Awaited<ReturnType<HostGitHubClient["getOctokit"]>>;

type Write = {
  octokit: Octokit;
  owner: string;
  repo: string;
  window: string;
  reason: string;
  files: File[];
  base: string;
  branch: string;
};

export default defineTool({
  description: "Skip or open an AGENTS.md follow-up PR for this weekly review. Call once.",
  effect: (input) => (input.verdict === "update" ? "write" : "read"),
  inputSchema: z.discriminatedUnion("verdict", [
    z.object({
      verdict: z.literal("skip"),
      reason: z.string().min(1).max(280),
    }),
    z.object({
      verdict: z.literal("update"),
      reason: z.string().min(1).max(280),
      files: z.array(file).min(1).max(8),
    }),
  ]),
  async execute(input, ctx) {
    if (ctx.session.purpose === "eval") {
      return { posted: false, reason: "eval", verdict: input.verdict };
    }
    if (input.verdict === "skip") {
      return { posted: false, reason: input.reason, verdict: "skip" };
    }
    const dir = ctx.workspaceDir;
    const repo = parseRepo(await readTrimmed(dir, "week/repo.txt"));
    const base = await readTrimmed(dir, "week/base.ref");
    const window = await readTrimmed(dir, "week/window.txt");
    const branch = updateBranch(base);
    if (repo === undefined || branch === undefined || window === "") {
      throw new Error("missing week/repo.txt, week/base.ref, or week/window.txt");
    }
    const files = input.files.map((item) => {
      const path = agentsPath(item.path);
      if (path === undefined) {
        throw new Error(`invalid AGENTS.md path: ${item.path}`);
      }
      return { path, content: item.content };
    });
    return openAgentsPr({
      octokit: await ctx.host.github.getOctokit(),
      owner: repo.owner,
      repo: repo.repo,
      window,
      reason: input.reason,
      files,
      base,
      branch,
    });
  },
});

async function openAgentsPr(input: Write) {
  const repo = { owner: input.owner, repo: input.repo };
  const existing = await input.octokit.rest.pulls.list({
    ...repo,
    state: "open",
    head: `${input.owner}:${input.branch}`,
    base: input.base,
    per_page: 1,
  });
  const open = existing.data[0];
  if (open !== undefined && citesWindow(open.body, input.window)) {
    return {
      posted: false,
      reason: "exists",
      verdict: "update",
      window: input.window,
      url: open.html_url,
    };
  }
  const branchSha = await refSha(input.octokit, repo, input.branch);
  const parent = branchSha ?? (await refSha(input.octokit, repo, input.base));
  if (parent === undefined) {
    throw new Error(`missing base ref: ${input.base}`);
  }
  const { data: commit } = await input.octokit.rest.git.getCommit({
    ...repo,
    commit_sha: parent,
  });
  const blobs = await Promise.all(
    input.files.map(async (item) => {
      const { data } = await input.octokit.rest.git.createBlob({
        ...repo,
        content: Buffer.from(item.content).toString("base64"),
        encoding: "base64",
      });
      return {
        path: item.path,
        mode: "100644" as const,
        type: "blob" as const,
        sha: data.sha,
      };
    }),
  );
  const { data: tree } = await input.octokit.rest.git.createTree({
    ...repo,
    base_tree: commit.tree.sha,
    tree: blobs,
  });
  const { data: next } = await input.octokit.rest.git.createCommit({
    ...repo,
    message: `agents.md: ${input.reason}`,
    tree: tree.sha,
    parents: [parent],
  });
  if (branchSha === undefined) {
    await input.octokit.rest.git.createRef({
      ...repo,
      ref: `refs/heads/${input.branch}`,
      sha: next.sha,
    });
  } else {
    await input.octokit.rest.git.updateRef({
      ...repo,
      ref: `heads/${input.branch}`,
      sha: next.sha,
    });
  }
  if (open !== undefined) {
    await input.octokit.rest.pulls.update({
      ...repo,
      pull_number: open.number,
      body: appendWindow(open.body ?? "", input.reason, input.window),
    });
    return {
      posted: true,
      verdict: "update",
      window: input.window,
      url: open.html_url,
    };
  }
  const { data: pull } = await input.octokit.rest.pulls.create({
    ...repo,
    title: `agents.md: update for ${input.window}`,
    head: input.branch,
    base: input.base,
    draft: true,
    body: pullBody(input.reason, input.window),
  });
  return {
    posted: true,
    verdict: "update",
    window: input.window,
    url: pull.html_url,
  };
}

async function readTrimmed(dir: string, rel: string): Promise<string> {
  return (await readFile(join(dir, rel), "utf8")).trim();
}

async function refSha(
  octokit: Octokit,
  repo: { owner: string; repo: string },
  name: string,
): Promise<string | undefined> {
  try {
    const { data } = await octokit.rest.git.getRef({
      ...repo,
      ref: `heads/${name}`,
    });
    return data.object.sha;
  } catch (error) {
    if (isNotFound(error)) {
      return undefined;
    }
    throw error;
  }
}

function pullBody(reason: string, window: string): string {
  return `${reason}

Window: ${window}

This pull request rewrites AGENTS.md. Those files are always-applied agent instructions. Review the bodies, then mark the draft ready and merge.`;
}

function citesWindow(body: string | null | undefined, window: string): boolean {
  return new RegExp(`(?:^|\\n)Window: ${escapeRegExp(window)}(?:\\s|$)`).test(body ?? "");
}

function appendWindow(body: string, reason: string, window: string): string {
  return `${body.trim()}\n\n${reason}\nWindow: ${window}`;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function isNotFound(error: unknown): boolean {
  return typeof error === "object" && error !== null && "status" in error && error.status === 404;
}
